<dl class="project-issue-summary"><div><dt>{{ trans('projects.actor') }}</dt><dd>{{ $snapshot['issuer_name'] ?? '' }}</dd></div><div><dt>{{ trans('projects.employee_barcode') }}</dt><dd>{{ $snapshot['recipient_employee_number'] ?? '' }}</dd></div><div><dt>{{ trans('projects.date_issued') }}</dt><dd><time datetime="{{ \Carbon\Carbon::parse($issue->created_at)->toIso8601String() }}" data-project-time>{{ $issue->created_at }}</time></dd></div><div><dt>{{ trans('projects.return_by') }}</dt><dd>{{ $issue->expected_checkin }}</dd></div><div><dt>{{ trans('projects.notification') }}</dt><dd>{{ trans('projects.notification_'.$issue->notification_status) }}</dd></div><div><dt>{{ trans('projects.handover') }}</dt><dd>{{ $issue->handed_over_at ? trans('projects.handed_over').' · '.$issue->handed_over_at : (!empty($snapshot['planned_handover_at']) ? trans('projects.handover_planned').' · '.$snapshot['planned_handover_at'] : ($issue->handover_declared_at ? trans('projects.handover_declared').' · '.$issue->handover_declared_at : trans('projects.handover_not_declared'))) }}</dd></div><div><dt>{{ trans('general.asset_model') }}</dt><dd>{{ $snapshot['model'] ?? '' }}</dd></div><div><dt>{{ trans('projects.condition') }}</dt><dd>{{ ($snapshot['condition'] ?? 'not_recorded') === 'not_recorded' ? trans('projects.not_recorded') : ($snapshot['condition'] ?? '') }}</dd></div><div><dt>{{ trans('general.serial') }}</dt><dd>{{ $snapshot['serial'] ?? '' }}</dd></div><div><dt>{{ trans('projects.issue_note') }}</dt><dd>{{ $issue->issue_note }}</dd></div><div><dt>{{ trans('projects.signature') }}</dt><dd>{{ $issue->accepted_at ?? $issue->declined_at ?? trans('projects.pending_acceptance') }}</dd></div></dl>
@if((int)$session->created_by === auth()->id() && !$issue->accepted_at && !$issue->declined_at && !$issue->cancelled_at && in_array($issue->notification_status,['failed','missing_email','not_sent']))<form method="post" action="{{ route('projects.issue.resend',[$session->id,$issue->id]) }}">@csrf<button type="submit" class="btn btn-default">{{ trans('projects.resend') }}</button></form>@endif
